using System.Collections.Generic;
using UnityEngine;
using static ResolverMaster.Core.UI.SdfArt;

namespace ResolverMaster.Games.Penguin.View
{
    /// <summary>
    /// Provisional Pingù art generated by code (PG-001), seen from above in a cartoon style with black outlines (the final drawings will
    /// come later): the penguin in layers (body, one face per expression: normal, happy, scared, dizzy; scarf and its stripes, tinted with
    /// the penguin color), the igloo (dome, the ice plate closing the door, the flag and its stripes), fish, rock, snow pile, water hole,
    /// ice block, the border pieces (snow wall, water, corner), the light bulb arrow, a splash ring and a sparkle, a plain ice tile.
    /// Every texture has <see cref="PenguinConfig.spritePixelsPerCell"/> pixels per cell. Cached per set of config values for the whole run.
    /// </summary>
    public sealed class PenguinSprites
    {
        public enum Face
        {
            Normal,
            Happy,
            Scared,
            Dizzy,
        }

        static readonly Dictionary<string, PenguinSprites> s_cache = new Dictionary<string, PenguinSprites>();

        public Sprite Body, Scarf, ScarfStripes;
        public readonly Sprite[] Faces = new Sprite[4];
        public Sprite Igloo, IglooClosed, Flag, FlagStripes;
        public Sprite Fish, Rock, Snow, Water, Block;
        public Sprite WallEdge, WaterEdge, Corner;
        public Sprite Arrow, Splash, Sparkle, Tile;

        public Sprite FaceSprite(Face f) => Faces[(int)f];

        public static PenguinSprites For(PenguinConfig cfg)
        {
            string key = string.Join("|", cfg.spritePixelsPerCell, cfg.outline, cfg.borderDepth, cfg.penguinBody, cfg.penguinBelly, cfg.penguinBeak,
                cfg.fishColor, cfg.fishFin, cfg.rockColor, cfg.rockShade, cfg.snowColor, cfg.snowShade, cfg.waterColor, cfg.waterDeep, cfg.blockColor,
                cfg.blockShade, cfg.iglooColor, cfg.iglooShade, cfg.iglooDoor, cfg.iglooClosed);
            if (s_cache.TryGetValue(key, out var cached) && cached.IsAlive) return cached;
            var s = new PenguinSprites();
            s.Generate(cfg);
            s_cache[key] = s;
            return s;
        }

        bool IsAlive => Body != null && Scarf != null && Igloo != null && Fish != null && Rock != null && Snow != null && Water != null && Block != null &&
                        WallEdge != null && WaterEdge != null && Arrow != null && Tile != null && Faces[0] != null && Faces[3] != null;

        static readonly Color Clear = new Color(0, 0, 0, 0);

        void Generate(PenguinConfig cfg)
        {
            int ppc = Mathf.Clamp(cfg.spritePixelsPerCell, 32, 512);
            float ol = cfg.outline;
            Color body = cfg.penguinBody, belly = cfg.penguinBelly, beak = cfg.penguinBeak;

            // ---- penguin: feet, round body and head, flippers, white belly and face, beak (facing the player, seen from above)
            Body = Draw("pg_penguin_body", ppc, 1, 1, p =>
            {
                var c = Clear;
                foreach (float x in new[] { 0.38f, 0.62f })
                    c = Over(c, Shape(Ellipse(p, new Vector2(x, 0.11f), new Vector2(0.1f, 0.06f)), ol * 0.8f, beak, ppc));
                float shape = Mathf.Min(Ellipse(p, new Vector2(0.5f, 0.4f), new Vector2(0.3f, 0.3f)), Ellipse(p, new Vector2(0.5f, 0.66f), new Vector2(0.22f, 0.21f)));
                shape = Mathf.Min(shape, Mathf.Min(Ellipse(p, new Vector2(0.21f, 0.4f), new Vector2(0.07f, 0.15f)), Ellipse(p, new Vector2(0.79f, 0.4f), new Vector2(0.07f, 0.15f))));
                c = Over(c, Shape(shape, ol, body, ppc));
                c = Over(c, Coverage(Ellipse(p, new Vector2(0.5f, 0.36f), new Vector2(0.2f, 0.22f)), ppc, belly));
                c = Over(c, Coverage(Ellipse(p, new Vector2(0.5f, 0.65f), new Vector2(0.15f, 0.12f)), ppc, belly));
                c = Over(c, Coverage(Ellipse(p, new Vector2(0.4f, 0.79f), new Vector2(0.05f, 0.025f)), ppc, new Color(1, 1, 1, 0.35f)));   // shine on the head
                c = Over(c, Shape(Ellipse(p, new Vector2(0.5f, 0.6f), new Vector2(0.065f, 0.04f)), ol * 0.6f, beak, ppc));
                return c;
            });
            Faces[(int)Face.Normal] = Draw("pg_face_normal", ppc, 1, 1, p =>
            {
                var c = Clear;
                foreach (float x in new[] { 0.44f, 0.56f })
                {
                    c = Over(c, Coverage(Ellipse(p, new Vector2(x, 0.68f), new Vector2(0.028f, 0.034f)), ppc, Color.black));
                    c = Over(c, Coverage((p - new Vector2(x + 0.008f, 0.69f)).magnitude - 0.009f, ppc, Color.white));
                }
                return c;
            });
            Faces[(int)Face.Happy] = Draw("pg_face_happy", ppc, 1, 1, p =>
            {
                var c = Clear;
                foreach (float x in new[] { 0.44f, 0.56f })
                {
                    // "^" eyes: the upper half of a small ring
                    var o = new Vector2(x, 0.665f);
                    float ring = Mathf.Abs((p - o).magnitude - 0.03f) - 0.009f;
                    if (p.y < o.y) ring = Mathf.Max(ring, (o.y - p.y) * 4f);
                    c = Over(c, Coverage(ring, ppc, Color.black));
                    c = Over(c, Coverage(Ellipse(p, new Vector2(x + (x < 0.5f ? -0.05f : 0.05f), 0.62f), new Vector2(0.03f, 0.016f)), ppc, new Color(1f, 0.55f, 0.6f, 0.75f)));
                }
                return c;
            });
            Faces[(int)Face.Scared] = Draw("pg_face_scared", ppc, 1, 1, p =>
            {
                var c = Clear;
                foreach (float x in new[] { 0.435f, 0.565f })
                {
                    c = Over(c, Shape((p - new Vector2(x, 0.69f)).magnitude - 0.042f, ol * 0.45f, Color.white, ppc));
                    c = Over(c, Coverage((p - new Vector2(x, 0.69f)).magnitude - 0.013f, ppc, Color.black));
                }
                // a drop of sweat by the head
                float drop = Mathf.Min((p - new Vector2(0.76f, 0.74f)).magnitude - 0.04f, Seg(p, new Vector2(0.76f, 0.75f), new Vector2(0.76f, 0.83f)) - 0.012f);
                c = Over(c, Shape(drop, ol * 0.4f, new Color(0.75f, 0.9f, 1f, 1f), ppc));
                return c;
            });
            Faces[(int)Face.Dizzy] = Draw("pg_face_dizzy", ppc, 1, 1, p =>
            {
                var c = Clear;
                foreach (float x in new[] { 0.44f, 0.56f })
                {
                    var o = new Vector2(x, 0.685f);
                    float d = Mathf.Min(Seg(p, o + new Vector2(-0.026f, -0.026f), o + new Vector2(0.026f, 0.026f)), Seg(p, o + new Vector2(-0.026f, 0.026f), o + new Vector2(0.026f, -0.026f))) - 0.009f;
                    c = Over(c, Coverage(d, ppc, Color.black));
                }
                // little stars around the head
                foreach (var s in new[] { new Vector2(0.28f, 0.88f), new Vector2(0.5f, 0.94f), new Vector2(0.72f, 0.88f) })
                    c = Over(c, Shape(Star(p, s, 0.045f), ol * 0.35f, new Color(1f, 0.92f, 0.45f, 1f), ppc));
                return c;
            });
            Scarf = Draw("pg_scarf", ppc, 1, 1, p => Shape(ScarfShape(p), ol * 0.8f, Color.white, ppc));
            ScarfStripes = Draw("pg_scarf_stripes", ppc, 1, 1, p =>
            {
                if (ScarfShape(p) > -ol * 0.8f) return Clear;
                float band = Mathf.Repeat((p.x + p.y) / 0.06f, 1f);
                return band < 0.45f ? new Color(0, 0, 0, 0.42f) : new Color(1, 1, 1, 0.35f);
            });

            // ---- igloo: dome of snow blocks, the dark door; the ice plate closing it; the flag (tinted) and its stripes
            Color ig = cfg.iglooColor, igShade = cfg.iglooShade;
            Igloo = Draw("pg_igloo", ppc, 1, 1, p =>
            {
                var c = Clear;
                c = Over(c, Coverage(Seg(p, new Vector2(0.73f, 0.5f), new Vector2(0.73f, 0.95f)) - 0.014f, ppc, new Color(0.25f, 0.22f, 0.2f, 1f)));   // flag pole
                float dome = Mathf.Max(Ellipse(p, new Vector2(0.5f, 0.12f), new Vector2(0.44f, 0.6f)), 0.08f - p.y);
                var col = Color.Lerp(igShade, ig, Mathf.Clamp01((p.y - 0.08f) / 0.5f));
                c = Over(c, Shape(dome, ol, col, ppc));
                if (dome < -ol)
                {
                    foreach (float y in new[] { 0.26f, 0.42f, 0.56f })
                        c = Over(c, Coverage(Mathf.Abs(p.y - y) - 0.006f, ppc, new Color(igShade.r * 0.85f, igShade.g * 0.85f, igShade.b * 0.9f, 0.9f)));
                    int row = p.y < 0.26f ? 0 : p.y < 0.42f ? 1 : p.y < 0.56f ? 2 : 3;
                    float joint = Mathf.Abs(Mathf.Repeat(p.x + row * 0.09f, 0.18f) - 0.09f) - 0.005f;
                    if (row < 3) c = Over(c, Coverage(joint, ppc, new Color(igShade.r * 0.85f, igShade.g * 0.85f, igShade.b * 0.9f, 0.8f)));
                }
                c = Over(c, Shape(Door(p, 0f), ol * 0.8f, cfg.iglooDoor, ppc));
                return c;
            });
            IglooClosed = Draw("pg_igloo_closed", ppc, 1, 1, p =>
            {
                float d = Door(p, 0.012f);
                var c = Shape(d, ol * 0.7f, cfg.iglooClosed, ppc);
                if (d < -ol * 0.7f && Mathf.Abs(p.x - p.y * 0.6f - 0.33f) < 0.012f) c = Over(c, new Color(1, 1, 1, 0.75f));
                return c;
            });
            Flag = Draw("pg_flag", ppc, 1, 1, p => Shape(FlagShape(p), ol * 0.7f, Color.white, ppc));
            FlagStripes = Draw("pg_flag_stripes", ppc, 1, 1, p =>
            {
                if (FlagShape(p) > -ol * 0.7f) return Clear;
                return Mathf.Repeat(p.x / 0.05f, 1f) < 0.5f ? new Color(0, 0, 0, 0.42f) : new Color(1, 1, 1, 0.35f);
            });

            // ---- fish (tail to the right), rock, snow pile, water hole, ice block
            Fish = Draw("pg_fish", ppc, 1, 1, p =>
            {
                var c = Clear;
                float tail = Mathf.Max(Mathf.Abs(p.y - 0.5f) - (p.x - 0.62f) * 0.9f, Mathf.Max(0.6f - p.x, p.x - 0.82f));
                c = Over(c, Shape(tail, ol * 0.8f, cfg.fishFin, ppc));
                c = Over(c, Shape(Ellipse(p, new Vector2(0.44f, 0.5f), new Vector2(0.24f, 0.14f)), ol * 0.8f, cfg.fishColor, ppc));
                c = Over(c, Coverage(Ellipse(p, new Vector2(0.42f, 0.56f), new Vector2(0.14f, 0.035f)), ppc, new Color(1, 1, 1, 0.35f)));
                c = Over(c, Coverage((p - new Vector2(0.3f, 0.53f)).magnitude - 0.022f, ppc, Color.black));
                c = Over(c, Coverage(Mathf.Abs((p - new Vector2(0.27f, 0.5f)).magnitude - 0.11f) - 0.006f + (p.x > 0.33f || p.y > 0.6f || p.y < 0.4f ? 1f : 0f), ppc, new Color(0, 0, 0, 0.5f)));
                return c;
            });
            Rock = Draw("pg_rock", ppc, 1, 1, p =>
            {
                float d = Mathf.Min(Ellipse(p, new Vector2(0.5f, 0.42f), new Vector2(0.39f, 0.29f)),
                    Mathf.Min(Ellipse(p, new Vector2(0.38f, 0.56f), new Vector2(0.23f, 0.21f)), Ellipse(p, new Vector2(0.63f, 0.55f), new Vector2(0.21f, 0.19f))));
                var col = Color.Lerp(cfg.rockShade, cfg.rockColor, Smooth(0.2f, 0.62f, p.y));
                var c = Shape(d, ol, col, ppc);
                if (d < -ol) c = Over(c, Coverage(Ellipse(p, new Vector2(0.36f, 0.62f), new Vector2(0.08f, 0.04f)), ppc, new Color(1, 1, 1, 0.3f)));
                c = Over(c, Coverage(Seg(p, new Vector2(0.55f, 0.36f), new Vector2(0.66f, 0.46f)) - 0.008f + Mathf.Max(0f, d + ol), ppc, new Color(0, 0, 0, 0.35f)));
                return c;
            });
            Snow = Draw("pg_snow", ppc, 1, 1, p =>
            {
                float d = Mathf.Min(RoundBox(p, new Vector2(0.5f, 0.4f), new Vector2(0.46f, 0.32f), 0.2f),
                    Mathf.Min(Ellipse(p, new Vector2(0.35f, 0.62f), new Vector2(0.24f, 0.2f)), Ellipse(p, new Vector2(0.66f, 0.6f), new Vector2(0.22f, 0.22f))));
                var col = Color.Lerp(cfg.snowShade, cfg.snowColor, Smooth(0.1f, 0.6f, p.y));
                var c = Shape(d, ol * 0.75f, col, ppc);
                if (d < -ol)
                    foreach (var s in new[] { new Vector2(0.3f, 0.66f), new Vector2(0.62f, 0.7f), new Vector2(0.5f, 0.4f), new Vector2(0.75f, 0.32f) })
                        c = Over(c, Coverage((p - s).magnitude - 0.012f, ppc, new Color(0.8f, 0.9f, 1f, 0.9f)));
                return c;
            });
            Water = Draw("pg_water", ppc, 1, 1, p =>
            {
                float d = RoundBox(p, new Vector2(0.5f, 0.5f), new Vector2(0.48f, 0.48f), 0.12f);
                var col = Color.Lerp(cfg.waterColor, cfg.waterDeep, Mathf.Clamp01(1f - (p - new Vector2(0.5f, 0.5f)).magnitude * 2f));
                var c = Shape(d, ol * 0.6f, col, ppc);
                if (d < -ol) c = Over(c, Waves(p, ppc, 0.2f));
                return c;
            });
            Block = Draw("pg_block", ppc, 1, 1, p =>
            {
                float d = RoundBox(p, new Vector2(0.5f, 0.5f), new Vector2(0.41f, 0.41f), 0.09f);
                var col = Color.Lerp(cfg.blockShade, cfg.blockColor, Smooth(0.1f, 0.8f, (p.y + 1f - p.x) * 0.5f));
                var c = Shape(d, ol, col, ppc);
                if (d < -ol)
                {
                    float inner = RoundBox(p, new Vector2(0.5f, 0.5f), new Vector2(0.29f, 0.29f), 0.06f);
                    c = Over(c, Coverage(Mathf.Abs(inner) - 0.008f, ppc, new Color(1, 1, 1, 0.55f)));
                    c = Over(c, Coverage(Seg(p, new Vector2(0.26f, 0.62f), new Vector2(0.38f, 0.74f)) - 0.016f, ppc, new Color(1, 1, 1, 0.85f)));
                    c = Over(c, Coverage(Seg(p, new Vector2(0.26f, 0.5f), new Vector2(0.3f, 0.54f)) - 0.012f, ppc, new Color(1, 1, 1, 0.7f)));
                }
                return c;
            });

            // ---- border pieces: one cell long, borderDepth deep; the side touching the cells is the bottom (y = 0)
            float depth = Mathf.Max(0.05f, cfg.borderDepth);
            WallEdge = Draw("pg_edge_wall", ppc, 1, depth, p =>
            {
                float top = depth * 0.78f + depth * 0.14f * Mathf.Sin(p.x * Mathf.PI * 2f * 2f);
                var col = Color.Lerp(cfg.snowShade, cfg.snowColor, Smooth(0f, depth, p.y));
                return Shape(Mathf.Max(p.y - top, -p.y), ol * 0.6f, col, ppc);
            });
            WaterEdge = Draw("pg_edge_water", ppc, 1, depth, p =>
            {
                var c = Over(new Color(cfg.waterColor.r, cfg.waterColor.g, cfg.waterColor.b, 1f), Waves(new Vector2(p.x, p.y * 2.2f), ppc, 0.25f));
                if (p.y < 0.025f) c = Color.Lerp(c, Color.black, 0.35f);
                return c;
            });
            Corner = Draw("pg_edge_corner", ppc, depth, depth, p =>
            {
                float d = (p - Vector2.zero).magnitude - depth * 0.92f;
                return Shape(d, ol * 0.6f, Color.Lerp(cfg.snowShade, cfg.snowColor, 0.6f), ppc);
            });

            // ---- the light bulb arrow (points up), a splash ring, a sparkle, a plain ice tile (no chapter theme)
            Arrow = Draw("pg_hint_arrow", ppc, 1, 1, p =>
            {
                float head = Mathf.Max(Mathf.Abs(p.x - 0.5f) * 1.1f + (p.y - 0.86f) * 0.62f, 0.5f - p.y);
                float shaft = RoundBox(p, new Vector2(0.5f, 0.32f), new Vector2(0.11f, 0.2f), 0.05f);
                return Fill(Mathf.Min(head, shaft), ol * 1.1f, Color.white, ppc);
            });
            Splash = Draw("pg_splash", ppc, 1, 1, p =>
            {
                var c = Coverage(Mathf.Abs((p - new Vector2(0.5f, 0.5f)).magnitude - 0.34f) - 0.035f, ppc, new Color(1, 1, 1, 0.9f));
                for (int i = 0; i < 8; i++)
                {
                    float a = i * Mathf.PI / 4f + 0.3f;
                    var s = new Vector2(0.5f + Mathf.Cos(a) * 0.43f, 0.5f + Mathf.Sin(a) * 0.43f);
                    c = Over(c, Shape((p - s).magnitude - 0.035f, ol * 0.35f, new Color(0.8f, 0.93f, 1f, 1f), ppc));
                }
                return c;
            });
            Sparkle = Draw("pg_sparkle", ppc, 1, 1, p => Shape(Star(p, new Vector2(0.5f, 0.5f), 0.3f), ol * 0.6f, new Color(1f, 0.93f, 0.5f, 1f), ppc));
            Tile = Draw("pg_tile", ppc, 1, 1, p => Fill(RoundBox(p, new Vector2(0.5f, 0.5f), new Vector2(0.47f, 0.47f), 0.1f), 0f, new Color(0.9f, 0.95f, 0.97f, 1f), ppc));
        }

        static float ScarfShape(Vector2 p) =>
            Mathf.Min(RoundBox(p, new Vector2(0.5f, 0.505f), new Vector2(0.235f, 0.042f), 0.04f), RoundBox(p, new Vector2(0.64f, 0.43f), new Vector2(0.045f, 0.085f), 0.035f));

        static float FlagShape(Vector2 p) => RoundBox(p, new Vector2(0.84f, 0.87f), new Vector2(0.11f, 0.075f), 0.02f);

        /// <summary>The door arch of the igloo (bottom centre), grown by <paramref name="grow"/>.</summary>
        static float Door(Vector2 p, float grow) =>
            Mathf.Min(RoundBox(p, new Vector2(0.5f, 0.19f), new Vector2(0.13f + grow, 0.11f + grow), 0f), (p - new Vector2(0.5f, 0.3f)).magnitude - (0.13f + grow));

        /// <summary>A five-pointed star of radius <paramref name="r"/> (approximate distance).</summary>
        static float Star(Vector2 p, Vector2 c, float r)
        {
            var q = p - c;
            float a = Mathf.Atan2(q.y, q.x) + Mathf.PI / 2f;
            float k = Mathf.Repeat(a, Mathf.PI * 2f / 5f) / (Mathf.PI * 2f / 5f);
            float edge = Mathf.Lerp(r * 0.45f, r, Mathf.Abs(k - 0.5f) * 2f);
            return q.magnitude - edge;
        }

        /// <summary>Short light wave strokes on the water.</summary>
        static Color Waves(Vector2 p, int ppc, float alpha)
        {
            float row = Mathf.Repeat(p.y / 0.22f, 1f);
            float shift = Mathf.Floor(p.y / 0.22f) * 0.17f;
            float wave = Mathf.Abs(row - 0.5f - 0.12f * Mathf.Sin((p.x + shift) * Mathf.PI * 2f * 2.5f)) * 0.22f - 0.012f;
            float dash = Mathf.Repeat(p.x * 2.5f + shift, 1f) < 0.55f ? 0f : 1f;
            return Coverage(wave + dash, ppc, new Color(1, 1, 1, alpha + 0.25f));
        }
    }
}
